import { useEffect, useMemo, useRef, useState } from "react";

/* ---------- world <-> view mapping ----------
   Part coords (mm): X longitudinal (nose -1693.8, tail +586.1),
   Y lateral (+/-345.02, 0 = centerline), Z vertical (floor 30, top 555).
   side view: u = x,  v = -z   (drag: dx=du, dz=-dv)   rotation normal: Y
   top  view: u = x,  v = -y   (drag: dx=du, dy=-dv)   rotation normal: Z
   rear view: u = -y, v = -z   (drag: dy=-du, dz=-dv)  rotation normal: X
------------------------------------------------ */
const VIEWS = {
  side: { label: "Side \u00b7 nose right", axes: ["x\u2192", "z\u2191"], proj: (p) => [-p[0], -p[2]], applyDrag: (pos, du, dv) => ({ ...pos, x: pos.x - du, z: pos.z - dv }), rotAxis: "ry", rotSign: 1, fit: [-650, -610, 2400, 640] },
  top: { label: "Top \u00b7 nose right", axes: ["x\u2192", "y\u2193"], proj: (p) => [-p[0], -p[1]], applyDrag: (pos, du, dv) => ({ ...pos, x: pos.x - du, y: pos.y - dv }), rotAxis: "rz", rotSign: 1, fit: [-650, -400, 2400, 800] },
  rear: { label: "Rear \u00b7 from behind", axes: ["y\u2192", "z\u2191"], proj: (p) => [p[1], -p[2]], applyDrag: (pos, du, dv) => ({ ...pos, y: pos.y + du, z: pos.z - dv }), rotAxis: "rx", rotSign: 1, fit: [-400, -610, 800, 640] },
};

// Projects a real-world (mm) opening's bounds into a view's u/v rect, so the
// clip window lines up with that view's own coordinate flip/orientation.
function projectWindowRect(vk, bounds) {
  if (vk === "top") {
    const { xMin, xMax, yMin, yMax } = bounds;
    return { x: -xMax, y: -yMax, w: xMax - xMin, h: yMax - yMin };
  }
  if (vk === "rear") {
    const { yMin, yMax, zMin, zMax } = bounds;
    return { x: yMin, y: -zMax, w: yMax - yMin, h: zMax - zMin };
  }
  return null;
}

const D2R = Math.PI / 180;
function rotMat(rx, ry, rz) {
  const a = rx * D2R, b = ry * D2R, c = rz * D2R;
  const ca = Math.cos(a), sa = Math.sin(a), cb = Math.cos(b), sb = Math.sin(b), cc = Math.cos(c), sc = Math.sin(c);
  // R = Rz * Ry * Rx
  return [
    [cc * cb, cc * sb * sa - sc * ca, cc * sb * ca + sc * sa],
    [sc * cb, sc * sb * sa + cc * ca, sc * sb * ca - cc * sa],
    [-sb, cb * sa, cb * ca],
  ];
}
function boxCorners(L, W, H, R, pos) {
  const h = [L / 2, W / 2, H / 2];
  const out = [];
  for (const i of [-1, 1]) for (const j of [-1, 1]) for (const k of [-1, 1]) {
    const l = [i * h[0], j * h[1], k * h[2]];
    out.push([
      R[0][0] * l[0] + R[0][1] * l[1] + R[0][2] * l[2] + pos.x,
      R[1][0] * l[0] + R[1][1] * l[1] + R[1][2] * l[2] + pos.y,
      R[2][0] * l[0] + R[2][1] * l[1] + R[2][2] * l[2] + pos.z,
    ]);
  }
  return out;
}
function hull(pts) {
  const P = [...pts].sort((p, q) => p[0] - q[0] || p[1] - q[1]);
  const cross = (o, a, b) => (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0]);
  const lo = [];
  for (const p of P) { while (lo.length >= 2 && cross(lo[lo.length - 2], lo[lo.length - 1], p) <= 0) lo.pop(); lo.push(p); }
  const up = [];
  for (let i = P.length - 1; i >= 0; i--) { const p = P[i]; while (up.length >= 2 && cross(up[up.length - 2], up[up.length - 1], p) <= 0) up.pop(); up.push(p); }
  return lo.slice(0, -1).concat(up.slice(0, -1));
}

const PALETTE = ["#4b2e83", "#b7791f", "#0f766e", "#b91c1c", "#1d4ed8", "#6d28d9", "#365314", "#9d174d"];
let uid = 1;
const mkComp = (n, over = {}) => ({
  id: "c" + uid++ + "_" + Date.now().toString(36),
  name: n, color: PALETTE[(uid - 2) % PALETTE.length],
  L: 300, W: 200, H: 150, cL: 10, cW: 10, cH: 10,
  x: 200, y: 0, z: 250, rx: 0, ry: 0, rz: 0, groupId: null, ...over,
});

const STORE_KEY = "t38-packaging-v1";
const MOCKUPS_KEY = "t38-packaging-mockups-v1";

function Num({ value, onChange, step = 1, w = 66 }) {
  const [txt, setTxt] = useState(null);
  return (
    <input
      className="num" style={{ width: w }} type="number" step={step}
      value={txt !== null ? txt : Math.round(value * 100) / 100}
      onChange={(e) => { setTxt(e.target.value); const v = parseFloat(e.target.value); if (!isNaN(v)) onChange(v); }}
      onBlur={() => setTxt(null)}
    />
  );
}

// Module-level (not defined inside T38Packaging's render) so React keeps the
// same component identity across re-renders instead of remounting the input
// and kicking focus out on every keystroke.
function F({ sel, upd, label, k, step = 1, w }) {
  return (
    <label className="fld"><span>{label}</span><Num value={sel[k]} step={step} w={w} onChange={(v) => upd(sel.id, { [k]: v })} /></label>
  );
}
function RotRow({ sel, upd, rotate, rotStep, axis, name }) {
  return (
    <div className="rotrow">
      <span className="rlbl">{name}</span>
      <button className="rb" onClick={() => rotate(sel.id, axis, -rotStep)}>⟲</button>
      <Num value={sel[axis]} step={rotStep} w={58} onChange={(v) => upd(sel.id, { [axis]: v })} />
      <button className="rb" onClick={() => rotate(sel.id, axis, rotStep)}>⟳</button>
    </div>
  );
}

// Small static side-view preview used on mockup cards in the drawer.
function MockupThumb({ comps }) {
  const V = VIEWS.side;
  return (
    <svg viewBox={V.fit.join(" ")} style={{ pointerEvents: "none" }}>
      <g className="mono">{GEOM.side.map((s, i) => <polyline key={i} points={s} />)}</g>
      {comps.map((c) => {
        const R = rotMat(c.rx, c.ry, c.rz);
        const ex = hull(boxCorners(c.L, c.W, c.H, R, c).map(V.proj));
        return <polygon key={c.id} className="mockthumb-comp" points={ex.map((p) => p.join(",")).join(" ")} fill={c.color} stroke={c.color} />;
      })}
    </svg>
  );
}

function View({ vk, comps, selId, onSelect, onDrag, onRotate, fw, setFw, solid, winRect }) {
  const V = VIEWS[vk];
  const wrapRef = useRef(null);
  const [vb, setVb] = useState(V.fit);
  const [pxW, setPxW] = useState(600);
  const dragRef = useRef(null);

  useEffect(() => {
    const el = wrapRef.current; if (!el) return;
    const ro = new ResizeObserver(() => setPxW(el.getBoundingClientRect().width || 600));
    ro.observe(el); return () => ro.disconnect();
  }, []);
  const scale = pxW / vb[2]; // px per mm

  const toMM = (e) => {
    const r = wrapRef.current.getBoundingClientRect();
    return [vb[0] + (e.clientX - r.left) / scale, vb[1] + (e.clientY - r.top) / scale];
  };

  const down = (e, comp) => {
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    const [u0, v0] = toMM(e);
    const group = comp && comp !== "fw" && comp.groupId ? comps.filter((c) => c.groupId === comp.groupId) : comp && comp !== "fw" ? [comp] : [];
    dragRef.current = comp === "fw"
      ? { kind: "fw", u0, x0: fw.x }
      : comp
      ? { kind: "comp", u0, v0, group: group.map((c) => ({ id: c.id, pos: { x: c.x, y: c.y, z: c.z } })) }
      : { kind: "pan", u0: e.clientX, v0: e.clientY, vb0: [...vb] };
    if (comp && comp !== "fw") onSelect(comp.id);
    else if (!comp) onSelect(null);
  };
  const move = (e) => {
    const d = dragRef.current; if (!d) return;
    if (d.kind === "fw") {
      const [u] = toMM(e);
      setFw((f) => ({ ...f, x: Math.round((d.x0 - (u - d.u0)) * 10) / 10 }));
    } else if (d.kind === "comp") {
      const [u, v] = toMM(e);
      const du = u - d.u0, dv = v - d.v0;
      d.group.forEach((g) => {
        const np = V.applyDrag(g.pos, du, dv);
        onDrag(g.id, { x: Math.round(np.x * 10) / 10, y: Math.round(np.y * 10) / 10, z: Math.round(np.z * 10) / 10 });
      });
    } else if (d.kind === "rot") {
      const dx = e.clientX - d.lastX;
      if (dx) onRotate(d.id, d.axis, dx * -0.5);
      d.lastX = e.clientX;
    } else if (d.kind === "fwtilt") {
      const dx = e.clientX - d.lastX;
      if (dx) setFw((f) => ({ ...f, tilt: Math.round((f.tilt + dx * -0.5) * 10) / 10 }));
      d.lastX = e.clientX;
    } else {
      setVb([d.vb0[0] - (e.clientX - d.u0) / scale, d.vb0[1] - (e.clientY - d.v0) / scale, d.vb0[2], d.vb0[3]]);
    }
  };
  const up = () => (dragRef.current = null);
  const wheel = (e) => {
    const [u, v] = toMM(e);
    const f = e.deltaY > 0 ? 1.15 : 1 / 1.15;
    setVb(([x, y, w, h]) => [u - (u - x) * f, v - (v - y) * f, w * f, h * f]);
  };

  const sel = comps.find((c) => c.id === selId);
  let rotUI = null;
  if (sel) {
    const R = rotMat(sel.rx, sel.ry, sel.rz);
    const pts = boxCorners(sel.L + 2 * sel.cL, sel.W + 2 * sel.cW, sel.H + 2 * sel.cH, R, sel).map(V.proj);
    const liveTop = Math.min(...pts.map((p) => p[1]));
    const liveCx = pts.reduce((s, p) => s + p[0], 0) / pts.length;
    // While actively dragging a handle, keep it fixed under the cursor instead of
    // letting it drift as the box's rotated bounding box changes shape mid-drag.
    const activeRot = dragRef.current?.kind === "rot" && dragRef.current.id === sel.id ? dragRef.current : null;
    const top = activeRot ? activeRot.top : liveTop;
    const cx = activeRot ? activeRot.cx : liveCx;
    const r = 13 / scale, gap = 26 / scale, yy = top - 22 / scale;
    const startRotDrag = (e) => {
      e.stopPropagation();
      e.currentTarget.setPointerCapture?.(e.pointerId);
      dragRef.current = { kind: "rot", id: sel.id, axis: V.rotAxis, lastX: e.clientX, top: liveTop, cx: liveCx };
    };
    const btn = (dx, dir, glyph) => (
      <g key={dir} transform={`translate(${cx + dx},${yy})`} className="rotbtn" onPointerDown={startRotDrag}>
        <circle r={r} />
        <text fontSize={15 / scale} dy={5 / scale}>{glyph}</text>
      </g>
    );
    rotUI = <g>{btn(-gap, -1, "⟲")}{btn(gap, 1, "⟳")}</g>;
  }

  return (
    <div className="viewwrap" ref={wrapRef}>
      <div className="viewtag">{V.label}<span className="viewaxes">{V.axes[0]} →, {V.axes[1]} ↑ · scroll zoom · drag bg pan</span></div>
      <svg viewBox={vb.join(" ")} onPointerDown={(e) => down(e, null)} onPointerMove={move} onPointerUp={up} onWheel={wheel}
        style={{ width: "100%", height: "100%", display: "block", touchAction: "none", cursor: "grab" }}>
        <g className="mono">{GEOM[vk].map((s, i) => <polyline key={i} points={s} />)}</g>
        {solid && winRect && (
          <defs>
            <clipPath id={`clip-${vk}`}>
              <rect x={winRect.x} y={winRect.y} width={winRect.w} height={winRect.h} />
            </clipPath>
          </defs>
        )}
        <g clipPath={solid && winRect ? `url(#clip-${vk})` : undefined}>
          {comps.map((c) => {
            const R = rotMat(c.rx, c.ry, c.rz);
            const ex = hull(boxCorners(c.L, c.W, c.H, R, c).map(V.proj));
            const cu = hull(boxCorners(c.L + 2 * c.cL, c.W + 2 * c.cW, c.H + 2 * c.cH, R, c).map(V.proj));
            const isSel = c.id === selId;
            return (
              <g key={c.id} onPointerDown={(e) => down(e, c)} style={{ cursor: "move" }}>
                <polygon points={cu.map((p) => p.join(",")).join(" ")} fill="none" stroke={c.color} strokeWidth={1.2 / scale} strokeDasharray={`${5 / scale} ${4 / scale}`} opacity={0.85} />
                <polygon points={ex.map((p) => p.join(",")).join(" ")} fill={c.color} fillOpacity={solid ? 1 : isSel ? 0.32 : 0.16} stroke={c.color} strokeWidth={(isSel ? 2.2 : 1.3) / scale} />
                {vk === "top" && <text x={-c.x} y={-c.y} fontSize={12 / scale} textAnchor="middle" fill={c.color} className="complbl">{c.name}</text>}
              </g>
            );
          })}
        </g>
        {solid && winRect && (
          <rect x={winRect.x} y={winRect.y} width={winRect.w} height={winRect.h} className="winmarker" />
        )}
        {fw.show && (vk === "side" || vk === "top") && (() => {
          const lbl = `firewall x=${fw.x}` + (fw.tilt ? ` / ${fw.tilt}\u00b0` : "");
          if (vk === "side") {
            const zb = 30, zt = 555;
            const du = Math.tan(fw.tilt * D2R) * (zt - zb); // + tilt leans top rearward (+x)
            const liveCx = -(fw.x + du), liveTop = -zt;
            const activeTilt = dragRef.current?.kind === "fwtilt" ? dragRef.current : null;
            const cx = activeTilt ? activeTilt.cx : liveCx;
            const top = activeTilt ? activeTilt.top : liveTop;
            const r = 13 / scale, gap = 26 / scale, yy = top - 22 / scale;
            const startTiltDrag = (e) => {
              e.stopPropagation();
              e.currentTarget.setPointerCapture?.(e.pointerId);
              dragRef.current = { kind: "fwtilt", lastX: e.clientX, top: liveTop, cx: liveCx };
            };
            const tbtn = (dx, glyph) => (
              <g key={glyph} transform={`translate(${cx + dx},${yy})`} className="rotbtn" onPointerDown={startTiltDrag}>
                <circle r={r} />
                <text fontSize={15 / scale} dy={5 / scale}>{glyph}</text>
              </g>
            );
            return (
              <g className="fwline">
                <g onPointerDown={(e) => down(e, "fw")}>
                  <line x1={-fw.x} y1={-zb} x2={-(fw.x + du)} y2={-zt} />
                  <line className="fwhit" x1={-fw.x} y1={-zb} x2={-(fw.x + du)} y2={-zt} />
                  <text x={-(fw.x + du)} y={-zt - 8 / scale} fontSize={11 / scale}>{lbl}</text>
                </g>
                {tbtn(-gap, "⟲")}
                {tbtn(gap, "⟳")}
              </g>
            );
          }
          return (
            <g className="fwline" onPointerDown={(e) => down(e, "fw")}>
              <line x1={-fw.x} y1={-360} x2={-fw.x} y2={360} />
              <line className="fwhit" x1={-fw.x} y1={-360} x2={-fw.x} y2={360} />
              <text x={-fw.x} y={-366} fontSize={11 / scale} textAnchor="middle">{lbl}</text>
            </g>
          );
        })()}
        {rotUI}
      </svg>
    </div>
  );
}

export default function T38Packaging() {
  const [comps, setComps] = useState(null);
  const [fw, setFw] = useState({ x: -131, tilt: 0, show: true });
  const [selId, setSelId] = useState(null);
  const [multiSel, setMultiSel] = useState(() => new Set());
  const [rotStep, setRotStep] = useState(15);
  const [saved, setSaved] = useState("");
  const [mockups, setMockups] = useState([]);
  const [mockupName, setMockupName] = useState("");
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [listH, setListH] = useState(220);
  const [solidView, setSolidView] = useState({ side: false, top: false, rear: false });
  const [windows, setWindows] = useState({
    // Rough estimates — tune these to match the real raincover/rear cutout openings.
    raincover: { xMin: -900, xMax: -350, yMin: -200, yMax: 200 },
    rearCutout: { yMin: -150, yMax: 150, zMin: 150, zMax: 450 },
  });
  const resizeRef = useRef(null);
  const dragCompId = useRef(null);
  const tRef = useRef(null);

  const startResize = (e) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    resizeRef.current = { y0: e.clientY, h0: listH };
  };
  const onResizeMove = (e) => {
    const r = resizeRef.current; if (!r) return;
    setListH(Math.max(80, Math.min(window.innerHeight * 0.65, r.h0 + (e.clientY - r.y0))));
  };
  const onResizeUp = () => { resizeRef.current = null; };

  useEffect(() => {
    (async () => {
      try {
        const r = await window.storage.get(STORE_KEY);
        const data = JSON.parse(r.value);
        uid = data.uid || 100;
        setComps(data.comps);
        if (data.fw) setFw(data.fw);
        if (data.solidView) setSolidView(data.solidView);
        if (data.windows) setWindows(data.windows);
        return;
      } catch (_) {}
      setComps([mkComp("Accumulator", { L: 600, W: 500, H: 340, x: 150, y: 0, z: 210, cL: 15, cW: 15, cH: 15 })]);
    })();
  }, []);

  useEffect(() => {
    if (!comps) return;
    clearTimeout(tRef.current);
    tRef.current = setTimeout(async () => {
      try { await window.storage.set(STORE_KEY, JSON.stringify({ comps, uid, fw, solidView, windows })); setSaved("saved " + new Date().toLocaleTimeString()); }
      catch (_) { setSaved("save failed"); }
    }, 700);
  }, [comps, fw, solidView, windows]);

  useEffect(() => {
    (async () => {
      try {
        const r = await window.storage.get(MOCKUPS_KEY);
        setMockups(JSON.parse(r.value) || []);
      } catch (_) { setMockups([]); }
    })();
  }, []);

  // Undo/redo: coalesce bursts of change (a drag, a run of keystrokes) into a
  // single history entry instead of recording every intermediate frame.
  const historyRef = useRef([]);
  const redoRef = useRef([]);
  const pendingRef = useRef(null);
  const historyTimer = useRef(null);
  useEffect(() => {
    if (!comps) return;
    if (pendingRef.current === null) { pendingRef.current = { comps, fw }; return; }
    clearTimeout(historyTimer.current);
    historyTimer.current = setTimeout(() => {
      historyRef.current.push(pendingRef.current);
      if (historyRef.current.length > 100) historyRef.current.shift();
      redoRef.current = [];
      pendingRef.current = { comps, fw };
    }, 400);
  }, [comps, fw]);

  useEffect(() => {
    const onKey = (e) => {
      if (["INPUT", "TEXTAREA"].includes(e.target.tagName)) return;
      const mod = e.metaKey || e.ctrlKey;
      if (mod && e.key.toLowerCase() === "z") {
        e.preventDefault();
        if (!comps) return;
        clearTimeout(historyTimer.current);
        if (e.shiftKey) {
          const next = redoRef.current.pop();
          if (!next) return;
          historyRef.current.push({ comps, fw });
          pendingRef.current = next;
          setComps(next.comps);
          setFw(next.fw);
        } else {
          const prev = historyRef.current.pop();
          if (!prev) return;
          redoRef.current.push({ comps, fw });
          pendingRef.current = prev;
          setComps(prev.comps);
          setFw(prev.fw);
        }
        return;
      }
      if ((e.key === "Delete" || e.key === "Backspace") && comps && selId) {
        e.preventDefault();
        setComps((cs) => cs.filter((c) => c.id !== selId));
        setSelId(null);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [comps, fw, selId]);

  const persistMockups = async (list) => {
    setMockups(list);
    try { await window.storage.set(MOCKUPS_KEY, JSON.stringify(list)); } catch (_) {}
  };
  const saveMockup = () => {
    const name = mockupName.trim();
    if (!name) return;
    const snap = { id: "m" + Date.now().toString(36), name, savedAt: new Date().toISOString(), comps, uid, fw };
    persistMockups([...mockups, snap]);
    setMockupName("");
  };
  const loadMockup = (m) => {
    if (!window.confirm(`Load "${m.name}"? This replaces the current layout (still saved under Mockups).`)) return;
    uid = m.uid || uid;
    setComps(m.comps);
    setFw(m.fw || fw);
    setSelId(null);
  };
  const duplicateMockup = (m) => {
    persistMockups([...mockups, { ...m, id: "m" + Date.now().toString(36), name: m.name + " copy", savedAt: new Date().toISOString() }]);
  };
  const renameMockup = (id, name) => persistMockups(mockups.map((m) => (m.id === id ? { ...m, name } : m)));
  const deleteMockup = (id) => {
    if (!window.confirm("Delete this mockup?")) return;
    persistMockups(mockups.filter((m) => m.id !== id));
  };

  if (!comps) return <div className="loading">Loading layout…</div>;

  const upd = (id, patch) => setComps((cs) => cs.map((c) => (c.id === id ? { ...c, ...patch } : c)));
  const rotate = (id, axis, d) => setComps((cs) => cs.map((c) => (c.id === id ? { ...c, [axis]: ((c[axis] + d) % 360 + 360) % 360 } : c)));
  const sel = comps.find((c) => c.id === selId);

  const toggleMultiSel = (id) =>
    setMultiSel((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  const groupSelected = () => {
    if (multiSel.size < 2) return;
    const gid = "g" + Date.now().toString(36);
    setComps((cs) => cs.map((c) => (multiSel.has(c.id) ? { ...c, groupId: gid } : c)));
    setMultiSel(new Set());
  };
  const ungroupSelected = () => {
    if (!sel?.groupId) return;
    const gid = sel.groupId;
    setComps((cs) => cs.map((c) => (c.groupId === gid ? { ...c, groupId: null } : c)));
  };

  const reorderComps = (targetId) => {
    if (!dragCompId.current || dragCompId.current === targetId) return;
    setComps((cs) => {
      const ids = cs.map((c) => c.id).filter((id) => id !== dragCompId.current);
      ids.splice(ids.indexOf(targetId), 0, dragCompId.current);
      return ids.map((id) => cs.find((c) => c.id === id));
    });
  };

  return (
    <div className="app">
      <style>{CSS}</style>
      <aside className="panel">
        <div className="brand">T38 packaging<span>monocoque 2279.87 × 690.04 × 525.00 mm · exact STEP geometry · nose x=−1693.8 · cockpit −979…−322 · rear bulkhead x=+586.1 (face z 119.4–509.7, h 390.3) · y ±345.0 · z 30…555</span></div>
        <div className="row">
          <button className="btn primary" onClick={() => { const c = mkComp("Component " + comps.length); setComps((cs) => [...cs, c]); setSelId(c.id); }}>Add component</button>
          <button className="btn" disabled={!sel} onClick={() => { const c = { ...sel, id: "c" + uid++, name: sel.name + " copy", x: sel.x + 50, groupId: null }; setComps((cs) => [...cs, c]); setSelId(c.id); }}>Duplicate</button>
          <button className="btn" disabled={!sel} onClick={() => { const c = { ...sel, id: "c" + uid++ , name: sel.name + " copy", y: -sel.y, groupId: null }; setComps((cs) => [...cs, c]); setSelId(c.id); }}>Mirror ↔</button>
          <button className="btn danger" disabled={!sel} onClick={() => { setComps((cs) => cs.filter((c) => c.id !== sel.id)); setSelId(null); }}>Delete</button>
        </div>
        <div className="row">
          <button className="btn" disabled={multiSel.size < 2} onClick={groupSelected}>Group{multiSel.size >= 2 ? ` (${multiSel.size})` : ""}</button>
          <button className="btn" disabled={!sel?.groupId} onClick={ungroupSelected}>Ungroup</button>
        </div>
        <div className="hint" style={{ padding: "0 12px 8px" }}>Check components below, then hit Group. Dragging any member of a group moves the whole group.</div>
        <div className="complist" style={{ height: listH }}>
          {comps.map((c) => (
            <div
              key={c.id}
              className={"citem" + (c.id === selId ? " on" : "")}
              onClick={() => setSelId(c.id)}
              draggable
              onDragStart={() => { dragCompId.current = c.id; }}
              onDragOver={(e) => { e.preventDefault(); reorderComps(c.id); }}
              onDragEnd={() => { dragCompId.current = null; }}
            >
              <input type="checkbox" checked={multiSel.has(c.id)} onClick={(e) => e.stopPropagation()} onChange={() => toggleMultiSel(c.id)} />
              <i style={{ background: c.color }} />
              {c.groupId && <span title="Grouped" className="groupdot">⛓</span>}
              <input value={c.name} onChange={(e) => upd(c.id, { name: e.target.value })} onClick={(e) => e.stopPropagation()} />
              <em>{c.L}×{c.W}×{c.H}</em>
            </div>
          ))}
        </div>
        <div className="resize-handle" title="Drag to resize" onPointerDown={startResize} onPointerMove={onResizeMove} onPointerUp={onResizeUp} onPointerCancel={onResizeUp} />
        <div className="panel-scroll">
          {sel ? (
            <div className="editor">
              <div className="sect">Exact dimensions <em>mm, before rotation</em></div>
              <div className="grid3">
                <F sel={sel} upd={upd} label="L (x)" k="L" /><F sel={sel} upd={upd} label="W (y)" k="W" /><F sel={sel} upd={upd} label="H (z)" k="H" />
              </div>
              <div className="sect">Cushion <em>clearance per side</em></div>
              <div className="grid3">
                <F sel={sel} upd={upd} label="±L" k="cL" /><F sel={sel} upd={upd} label="±W" k="cW" /><F sel={sel} upd={upd} label="±H" k="cH" />
              </div>
              <div className="envelope">envelope {sel.L + 2 * sel.cL} × {sel.W + 2 * sel.cW} × {sel.H + 2 * sel.cH}</div>
              <div className="sect">Position <em>box center, part coords</em></div>
              <div className="grid3">
                <F sel={sel} upd={upd} label="x" k="x" step={5} /><F sel={sel} upd={upd} label="y" k="y" step={5} /><F sel={sel} upd={upd} label="z" k="z" step={5} />
              </div>
              <div className="sect">Rotation <em>deg · step
                <select value={rotStep} onChange={(e) => setRotStep(+e.target.value)}>{[5, 15, 45, 90].map((s) => <option key={s} value={s}>{s}°</option>)}</select></em>
              </div>
              <RotRow sel={sel} upd={upd} rotate={rotate} rotStep={rotStep} axis="rx" name="rx (roll)" />
              <RotRow sel={sel} upd={upd} rotate={rotate} rotStep={rotStep} axis="ry" name="ry (pitch)" />
              <RotRow sel={sel} upd={upd} rotate={rotate} rotStep={rotStep} axis="rz" name="rz (yaw)" />
              <div className="sect">Color</div>
              <div className="swatches">{PALETTE.map((p) => <b key={p} style={{ background: p, outline: sel.color === p ? "2px solid #111" : "none" }} onClick={() => upd(sel.id, { color: p })} />)}</div>
            </div>
          ) : (
            <div className="hint">Select a component to edit. Drag boxes in any view — position updates on the two in-plane axes. Arrows above a selected box rotate about that view's normal axis.</div>
          )}
          <div className="editor" style={{ borderTop: "1px solid #e3e3e3" }}>
            <div className="sect">Firewall <em>driver seatback plane</em></div>
            <div className="grid3">
              <label className="fld"><span>x station</span><Num value={fw.x} step={5} onChange={(v) => setFw((f) => ({ ...f, x: v }))} /></label>
              <label className="fld"><span>tilt °</span><Num value={fw.tilt} step={1} onChange={(v) => setFw((f) => ({ ...f, tilt: v }))} /></label>
              <label className="fld" style={{ display: "flex", alignItems: "flex-end", gap: 4 }}>
                <input type="checkbox" checked={fw.show} onChange={(e) => setFw((f) => ({ ...f, show: e.target.checked }))} /> show
              </label>
            </div>
          </div>
          <div className="editor" style={{ borderTop: "1px solid #e3e3e3" }}>
            <div className="sect">View display <em>solid hides everything but the opening</em></div>
            <div className="row" style={{ padding: "2px 0 8px" }}>
              {["side", "top", "rear"].map((vk) => (
                <label key={vk} className="fld" style={{ display: "flex", alignItems: "center", gap: 4 }}>
                  <input type="checkbox" checked={solidView[vk]} onChange={(e) => setSolidView((s) => ({ ...s, [vk]: e.target.checked }))} />
                  {vk} solid
                </label>
              ))}
            </div>
            {solidView.top && (
              <>
                <div className="sect" style={{ margin: "6px 0 4px" }}>Raincover opening <em>Top view, mm — rough estimate, tune to match</em></div>
                <div className="grid3">
                  <label className="fld"><span>x min</span><Num value={windows.raincover.xMin} step={5} onChange={(v) => setWindows((w) => ({ ...w, raincover: { ...w.raincover, xMin: v } }))} /></label>
                  <label className="fld"><span>x max</span><Num value={windows.raincover.xMax} step={5} onChange={(v) => setWindows((w) => ({ ...w, raincover: { ...w.raincover, xMax: v } }))} /></label>
                  <span />
                  <label className="fld"><span>y min</span><Num value={windows.raincover.yMin} step={5} onChange={(v) => setWindows((w) => ({ ...w, raincover: { ...w.raincover, yMin: v } }))} /></label>
                  <label className="fld"><span>y max</span><Num value={windows.raincover.yMax} step={5} onChange={(v) => setWindows((w) => ({ ...w, raincover: { ...w.raincover, yMax: v } }))} /></label>
                </div>
              </>
            )}
            {solidView.rear && (
              <>
                <div className="sect" style={{ margin: "6px 0 4px" }}>Rear cutout <em>Rear view, mm — rough estimate, tune to match</em></div>
                <div className="grid3">
                  <label className="fld"><span>y min</span><Num value={windows.rearCutout.yMin} step={5} onChange={(v) => setWindows((w) => ({ ...w, rearCutout: { ...w.rearCutout, yMin: v } }))} /></label>
                  <label className="fld"><span>y max</span><Num value={windows.rearCutout.yMax} step={5} onChange={(v) => setWindows((w) => ({ ...w, rearCutout: { ...w.rearCutout, yMax: v } }))} /></label>
                  <span />
                  <label className="fld"><span>z min</span><Num value={windows.rearCutout.zMin} step={5} onChange={(v) => setWindows((w) => ({ ...w, rearCutout: { ...w.rearCutout, zMin: v } }))} /></label>
                  <label className="fld"><span>z max</span><Num value={windows.rearCutout.zMax} step={5} onChange={(v) => setWindows((w) => ({ ...w, rearCutout: { ...w.rearCutout, zMax: v } }))} /></label>
                </div>
              </>
            )}
          </div>
          <div className="foot">{(saved || "autosaves to shared layout storage") + " · Ctrl/Cmd+Z to undo · Delete to remove selected"}<button className="link" onClick={async () => { try { await window.storage.delete(STORE_KEY); } catch (_) {} location.reload(); }}>reset layout</button></div>
        </div>
      </aside>
      <main className="views">
        <div className="vside"><View vk="side" comps={comps} selId={selId} onSelect={setSelId} onDrag={(id, p) => upd(id, p)} onRotate={rotate} fw={fw} setFw={setFw} solid={solidView.side} /></div>
        <div className="vtop"><View vk="top" comps={comps} selId={selId} onSelect={setSelId} onDrag={(id, p) => upd(id, p)} onRotate={rotate} fw={fw} setFw={setFw} solid={solidView.top} winRect={projectWindowRect("top", windows.raincover)} /></div>
        <div className="vrear"><View vk="rear" comps={comps} selId={selId} onSelect={setSelId} onDrag={(id, p) => upd(id, p)} onRotate={rotate} fw={fw} setFw={setFw} solid={solidView.rear} winRect={projectWindowRect("rear", windows.rearCutout)} /></div>
      </main>
      <div className={"mockdrawer" + (drawerOpen ? " open" : "")}>
        <button className="mockdrawer-tab" onClick={() => setDrawerOpen((v) => !v)}>Mockups {mockups.length ? `(${mockups.length})` : ""}</button>
        <div className="mockdrawer-head">
          <span>Mockups</span>
          <button className="link" onClick={() => setDrawerOpen(false)}>close ✕</button>
        </div>
        <div className="row" style={{ padding: "10px 12px", borderBottom: "1px solid #e3e3e3" }}>
          <input
            className="mockname-input"
            style={{ flex: 1 }}
            placeholder="Name this layout…"
            value={mockupName}
            onChange={(e) => setMockupName(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && saveMockup()}
          />
          <button className="btn primary" disabled={!mockupName.trim()} onClick={saveMockup}>Save</button>
        </div>
        <div className="mockcards">
          {mockups.length === 0 && <div className="hint">No saved mockups yet — name the current layout above and save it.</div>}
          {mockups.map((m) => (
            <div key={m.id} className="mockcard">
              <div className="mockthumb" onClick={() => loadMockup(m)} title="Load this mockup">
                <MockupThumb comps={m.comps} />
              </div>
              <input value={m.name} onChange={(e) => renameMockup(m.id, e.target.value)} />
              <div className="mockmeta">{new Date(m.savedAt).toLocaleDateString()} · {m.comps.length} comp{m.comps.length === 1 ? "" : "s"}</div>
              <div className="mockrow">
                <button className="btn" onClick={() => duplicateMockup(m)}>Duplicate</button>
                <button className="btn danger" onClick={() => deleteMockup(m.id)}>Delete</button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

const CSS = `
*{box-sizing:border-box;margin:0}
.app{display:flex;height:100%;background:#fff;color:#111;font:13px/1.45 -apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-variant-numeric:tabular-nums}
.loading{padding:40px;font:14px sans-serif}
.panel{width:300px;min-width:300px;border-right:1px solid #d8d8d8;display:flex;flex-direction:column;overflow:hidden;background:#fafafa}
.panel-scroll{flex:1;min-height:0;overflow-y:auto;display:flex;flex-direction:column}
.brand{padding:14px 14px 10px;border-bottom:1px solid #e3e3e3}
.brand{font-weight:700;font-size:15px;color:#4b2e83;letter-spacing:.2px}
.brand span{display:block;font-weight:400;font-size:10.5px;color:#777;margin-top:3px;line-height:1.5}
.row{display:flex;gap:6px;padding:10px 12px}
.btn{flex:1;padding:6px 4px;border:1px solid #bbb;background:#fff;cursor:pointer;font-size:12px}
.btn:hover{border-color:#4b2e83}
.btn.primary{background:#4b2e83;color:#fff;border-color:#4b2e83}
.btn.danger:hover{border-color:#b91c1c;color:#b91c1c}
.btn:disabled{opacity:.4;cursor:default}
.complist{border-top:1px solid #e3e3e3;flex:none;overflow-y:auto}
.resize-handle{flex:none;height:10px;cursor:row-resize;position:relative;background:#fafafa;touch-action:none}
.resize-handle::after{content:"";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:36px;height:4px;border-radius:2px;background:#d8d8d8}
.resize-handle:hover::after{background:#4b2e83}
.citem{display:flex;align-items:center;gap:7px;padding:5px 12px;cursor:grab;border-left:3px solid transparent}
.citem.on{background:#efe9f7;border-left-color:#4b2e83}
.citem i{width:10px;height:10px;flex:none}
.citem input[type=checkbox]{flex:none;width:13px;height:13px;margin:0}
.citem input:not([type=checkbox]){flex:1;border:none;background:transparent;font:inherit;min-width:0}
.citem em{font-style:normal;font-size:10.5px;color:#888;white-space:nowrap}
.groupdot{font-size:10px;flex:none}
.editor{padding:4px 12px 12px;border-top:1px solid #e3e3e3}
.sect{margin:12px 0 5px;font-weight:600;font-size:12px}
.sect em{font-weight:400;font-style:normal;color:#888;font-size:10.5px;margin-left:4px}
.sect select{margin-left:4px;font-size:11px}
.grid3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px}
.fld span{display:block;font-size:10.5px;color:#666;margin-bottom:2px}
.num{border:1px solid #ccc;padding:3px 4px;font:12px inherit;font-variant-numeric:tabular-nums}
.num:focus{outline:1px solid #4b2e83;border-color:#4b2e83}
.envelope{margin-top:6px;font-size:11px;color:#4b2e83}
.rotrow{display:flex;align-items:center;gap:6px;margin:4px 0}
.rlbl{width:64px;font-size:11.5px;color:#444}
.rb{width:28px;height:24px;border:1px solid #bbb;background:#fff;cursor:pointer;font-size:14px;line-height:1}
.rb:hover{border-color:#4b2e83;color:#4b2e83}
.swatches{display:flex;gap:6px}
.swatches b{width:18px;height:18px;cursor:pointer}
.hint{padding:14px;color:#777;font-size:12px}
.mockname-input{border:1px solid #ccc;padding:5px 7px;font:inherit;font-size:12px}
.mockdrawer{position:fixed;top:45px;right:0;width:250px;height:calc(100vh - 45px);background:#fff;border-left:1px solid #d8d8d8;box-shadow:-6px 0 16px rgba(0,0,0,.1);display:flex;flex-direction:column;transform:translateX(100%);transition:transform .22s ease;z-index:20}
.mockdrawer.open{transform:translateX(0)}
.mockdrawer-tab{position:absolute;top:50%;left:-32px;transform:translateY(-50%);width:32px;padding:14px 6px;background:#4b2e83;color:#fff;border:none;border-radius:6px 0 0 6px;cursor:pointer;font-size:11px;font-weight:600;writing-mode:vertical-rl;text-orientation:mixed;letter-spacing:.3px}
.mockdrawer-head{display:flex;align-items:center;justify-content:space-between;padding:12px;border-bottom:1px solid #e3e3e3;font-weight:700;font-size:13px}
.mockcards{flex:1;overflow-y:auto;padding:10px 12px}
.mockcard{border:1px solid #e3e3e3;padding:8px;margin-bottom:10px}
.mockthumb{border:1px solid #eee;background:#fafafa;height:64px;cursor:pointer;margin-bottom:6px}
.mockthumb:hover{border-color:#4b2e83}
.mockthumb svg{width:100%;height:100%;display:block}
.mockthumb-comp{fill-opacity:.55;stroke-width:1.4;vector-effect:non-scaling-stroke}
.mockcard input{width:100%;border:none;background:transparent;font:inherit;font-weight:600;font-size:12.5px;padding:2px 0;border-bottom:1px dashed transparent}
.mockcard input:hover,.mockcard input:focus{border-bottom-color:#bbb;outline:none}
.mockmeta{font-size:10px;color:#999;margin:2px 0 6px}
.mockrow{display:flex;gap:6px}
.mockrow .btn{flex:1;font-size:11px;padding:4px 2px}
.foot{margin-top:auto;padding:10px 12px;font-size:10.5px;color:#999;border-top:1px solid #e3e3e3;display:flex;justify-content:space-between;align-items:center}
.link{border:none;background:none;color:#4b2e83;cursor:pointer;font-size:10.5px;text-decoration:underline}
.views{flex:1;display:grid;grid-template-columns:1fr 340px;grid-template-rows:1fr 1fr;gap:1px;background:#d8d8d8;min-width:0}
.vside{grid-column:1;grid-row:1}.vtop{grid-column:1;grid-row:2}.vrear{grid-column:2;grid-row:1/3}
.viewwrap{position:relative;background:#fff;height:100%;overflow:hidden}
.viewtag{position:absolute;top:6px;left:10px;z-index:2;font-weight:700;font-size:12px;color:#4b2e83;pointer-events:none}
.viewaxes{font-weight:400;color:#aaa;margin-left:8px;font-size:10.5px}
.mono polyline{fill:none;stroke:#b9b9b9;stroke-width:.7;vector-effect:non-scaling-stroke}
.complbl{pointer-events:none;font-weight:600}
.fwline line{stroke:#b91c1c;stroke-width:1.6;stroke-dasharray:7 5;vector-effect:non-scaling-stroke}
.fwline .fwhit{stroke:transparent;stroke-width:14;stroke-dasharray:none;cursor:ew-resize}
.fwline text{fill:#b91c1c;font-weight:600}
.rotbtn{cursor:pointer}
.rotbtn circle{fill:#fff;stroke:#4b2e83;stroke-width:1.5;vector-effect:non-scaling-stroke}
.winmarker{fill:none;stroke:#0f766e;stroke-width:1.4;stroke-dasharray:6 4;vector-effect:non-scaling-stroke;pointer-events:none}
.rotbtn text{fill:#4b2e83;text-anchor:middle;user-select:none}
.rotbtn:hover circle{fill:#efe9f7}
@media (max-width:900px){.app{flex-direction:column;height:auto}.panel{width:100%;min-width:0}.views{grid-template-columns:1fr;grid-template-rows:260px 260px 300px}.vrear{grid-column:1;grid-row:3}}
`;
